hids<-unique(o$id_hogar);j<-match(hids,h$id_hogar);matchok<-!anyDuplicated(h$id_hogar)&&!anyNA(j)
if(!matchok){newblock('BLOCKED_SES_PROTOCOL','adjusted models','Household key uniqueness or full match failed','Resolve household source identities');g$OWOBNEW_SES_MCA_v1<-factor(NA,levels=c('High','Medium','Low'));savepriv(g,'governed_pivot.rds');wc(data.frame(check='household_match',value=FALSE,status='BLOCKED'),'SES_MCA_QA.csv')}else{
 ph<-h[j,];x<-as.data.frame(lapply(ph[items],function(v)factor(ifelse(v%in%c(1,2),v,NA),levels=c(2,1),labels=c('No','Yes'))));cc<-complete.cases(x);xc<-droplevels(x[cc,,drop=FALSE]);ids<-hids[cc]
 iq<-do.call(rbind,lapply(items,function(v){tb<-table(x[[v]],useNA='always');data.frame(variable=v,category=names(tb),households=as.integer(tb),proportion=as.numeric(tb)/nrow(x),invalid_raw=sum(!is.na(ph[[v]])&!ph[[v]]%in%c(1,2)))}));wc(iq,'SES_ITEM_FREQUENCIES.csv')
 cats<-unlist(lapply(xc,table));basic<-sum(cc)/nrow(x)>=.9&&all(vapply(xc,nlevels,0L)==2)&&all(cats>=20)&&all(cats/sum(cc)>=.01)
 if(!basic){newblock('BLOCKED_SES_PROTOCOL','adjusted models','Frozen missingness/rarity criteria failed','Review material-index protocol; crude analyses remain authorized');g$OWOBNEW_SES_MCA_v1<-factor(rep(NA_character_,nrow(g)),levels=c('High','Medium','Low'));savepriv(g,'governed_pivot.rds');wc(data.frame(check='coverage_and_rarity',value=FALSE,status='BLOCKED'),'SES_MCA_QA.csv')}else{
  fit<-ade4::dudi.acm(xc,scannf=FALSE,nf=5);score<-fit$li[,1];assets<-rowSums(xc=='Yes');sgn<-if(cor(score,assets,method='spearman')<0)-1 else 1;score<-sgn*score;zs<-as.numeric(scale(score));cuts<-as.numeric(quantile(score,c(1/3,2/3),type=1));tertile<-function(s){q<-as.numeric(quantile(s,c(1/3,2/3),type=1));factor(ifelse(s<=q[1],'Low',ifelse(s<=q[2],'Medium','High')),levels=c('High','Medium','Low'))};tt<-tertile(score)
  mass<-MASS::mca(xc,nf=2);massrho<-abs(cor(score,mass$rs[,1]));ev<-data.frame(axis=seq_along(fit$eig),eigenvalue=fit$eig,raw_inertia_pct=100*fit$eig/sum(fit$eig));wc(ev,'SES_MCA_INERTIA.csv')
  category<-do.call(rbind,lapply(items,function(v)do.call(rbind,lapply(levels(xc[[v]]),function(l){ix<-xc[[v]]==l;data.frame(variable=v,category=l,N=sum(ix),score_mean=mean(score[ix]),score_sd=sd(score[ix]),asset_count_mean=mean(assets[ix]))}))));wc(category,'SES_MCA_CATEGORY_GRADIENT.csv')
  coords<-data.frame(category=rownames(fit$co),axis1_coordinate=sgn*fit$co[,1],axis1_contribution_pct=100*fit$cw*(fit$co[,1]^2)/fit$eig[1]);wc(coords,'SES_MCA_CATEGORY_COORDINATES.csv')
  stab<-list();for(v in items){zz<-ade4::dudi.acm(xc[setdiff(items,v)],scannf=FALSE,nf=1)$li[,1];if(cor(zz,score)<0)zz<--zz;stab[[v]]<-data.frame(sensitivity=paste0('leave_out_',v),rho=cor(score,zz,method='spearman'),tertile_agreement=mean(tertile(zz)==tt),rho_min=.85,agreement_min=.70)}
  zz<-ade4::dudi.acm(xc[setdiff(items,c('f1_s1_42','f1_s1_43'))],scannf=FALSE,nf=1)$li[,1];if(cor(zz,score)<0)zz<--zz;stab[['access']]<-data.frame(sensitivity='omit_internet_and_cable',rho=cor(score,zz,method='spearman'),tertile_agreement=mean(tertile(zz)==tt),rho_min=.80,agreement_min=NA_real_);st<-do.call(rbind,stab);st$status<-ifelse(st$rho>=st$rho_min&(is.na(st$agreement_min)|st$tertile_agreement>=st$agreement_min),'PASS','BLOCKED');wc(st,'SES_MCA_STABILITY.csv')
  sv<-list(roof=list('f1_s1_3',1:4),floor=list('f1_s1_4',1:4),walls=list('f1_s1_5',1:2),electricity=list('f1_s1_10',1),sanitation=list('f1_s1_13',1:2),piped_water=list('f1_s1_21',1:3))
  supp<-do.call(rbind,lapply(names(sv),function(n){v<-ph[[sv[[n]][[1]]]][cc];do.call(rbind,lapply(c('Low','Medium','High'),function(t){i<-tt==t&!is.na(v);data.frame(indicator=n,source_variable=sv[[n]][[1]],tertile=t,N=sum(i),favorable_proportion=mean(v[i]%in%sv[[n]][[2]]))}))}));wc(supp,'SES_MCA_SUPPLEMENTARY_VALIDATION.csv')
  ndirection<-sum(vapply(items,function(v){s<-category[category$variable==v,];s$score_mean[s$category=='Yes']>s$score_mean[s$category=='No']},FALSE));nsupp<-sum(vapply(names(sv),function(v){s<-supp[supp$indicator==v,];s$favorable_proportion[s$tertile=='High']>s$favorable_proportion[s$tertile=='Low']},FALSE));pr<-table(tt)/length(tt)
  checks<-c('household_unique_match','household_complete_coverage','binary_item_rarity','asset_count_gradient','dominant_axis_ratio','MASS_implementation_correlation','distinct_tertile_cuts','tertile_sizes_15_50pct','asset_directions_at_least11','supplementary_directions_at_least4','prespecified_stability')
  values<-c(1,mean(cc),min(cats)/sum(cc),cor(score,assets,method='spearman'),fit$eig[1]/fit$eig[2],massrho,diff(cuts),min(pr),ndirection,nsupp,min(st$rho))
  pass<-c(matchok,mean(cc)>=.9,min(cats)>=20&&min(cats)/sum(cc)>=.01,values[4]>=.7,values[5]>=1.1,massrho>=.999999,diff(cuts)>0,all(pr>=.15&pr<=.5),ndirection>=11,nsupp>=4,all(st$status=='PASS'))
  qa<-data.frame(check=checks,value=values,status=ifelse(pass,'PASS','BLOCKED'),households_pivot=length(hids),households_complete=sum(cc),active_items=length(items));wc(qa,'SES_MCA_QA.csv')
  hs<-data.frame(id_hogar=ids,score_raw_oriented=score,score_standardized=zs,SES_candidate=tt);savepriv(hs,'SES_household_scores.rds');g$OWOBNEW_SES_SCORE<-zs[match(o$id_hogar,ids)];g$OWOBNEW_SES_MCA_v1<-factor(if(all(pass))as.character(tt[match(o$id_hogar,ids)])else rep(NA_character_,nrow(g)),levels=c('High','Medium','Low'))
  if(!all(pass))newblock('BLOCKED_SES_PROTOCOL','adjusted models',paste(checks[!pass],collapse=';'),'Resolve failed frozen SES validation; primary index not replaced by a sensitivity')
  savepriv(g,'governed_pivot.rds');wc(data.frame(tertile=c('Low','Medium','High'),households=as.integer(table(tt)[c('Low','Medium','High')]),participants=as.integer(table(g$OWOBNEW_SES_MCA_v1)[c('Low','Medium','High')]),status=if(all(pass))'READY'else'BLOCKED'),'SES_TERTILE_COUNTS.csv')
  wc(data.frame(cut=c('one_third','two_thirds'),score_cut=cuts,quantile_type=1,unit='one household one weight',sign_multiplier=sgn,axis=1,score_mean=mean(score),score_sd=sd(score)),'SES_FROZEN_CUTPOINTS.csv')
  frozen<-c('config/SES_ITEMS_FROZEN.csv','docs/OWOB01D_NEW_SES_MCA_METHOD.md','data/private/SES_household_scores.rds','outputs/qa/SES_FROZEN_CUTPOINTS.csv','outputs/qa/SES_MCA_QA.csv');freeze_csv(data.frame(path=frozen,sha256=vapply(frozen,sha,''),created_at=readLines('config/CREATED_AT.txt'),models_run_at_freeze=0),'config/SES_FREEZE.csv')
  cat('NEW SES:',if(all(pass))'READY'else'BLOCKED','; households',length(hids),'; complete',sum(cc),'; items',length(items),'\n');print(qa,row.names=FALSE);print(st,row.names=FALSE)
